insert into public.aula_teams(grade,parallel,group_number,color_name,color_hex,team_name,project_title,project_description,project_problem,project_solution) values(4,'B',1,'Rosado','#ef8fba','Grupo 1','Cuidado de la biodiversidad','Pollinator Home propone desarrollar maqueta y selección de materiales naturales para comunidad escolar en zoobotánica / área verde o especie seleccionada. El proyecto responde al problema «faltan refugios didácticos para insectos benéficos» y se probará con usuarios reales para comprobar número de elementos/refugios incorporados.','Faltan refugios didácticos para insectos benéficos','Pollinator Home propone desarrollar maqueta y selección de materiales naturales para comunidad escolar en zoobotánica / área verde o especie seleccionada. El proyecto responde al problema «faltan refugios didácticos para insectos benéficos» y se probará con usuarios reales para comprobar número de elementos/refugios incorporados.') on conflict(grade,parallel,group_number) do nothing;
