insert into public.aula_teams(grade,parallel,group_number,color_name,color_hex,team_name,project_title,project_description,project_problem,project_solution) values(4,'A',5,'Lila','#aa9cec','Grupo 5','Convivencia escolar','BancoAmistad Junior propone desarrollar señal y protocolo simple de acompañamiento para estudiantes en espacio escolar delimitado antes de iniciar. El proyecto responde al problema «algunos estudiantes quedan sin compañía en el recreo» y se probará con usuarios reales para comprobar interacciones positivas registradas.','Algunos estudiantes quedan sin compañía en el recreo','BancoAmistad Junior propone desarrollar señal y protocolo simple de acompañamiento para estudiantes en espacio escolar delimitado antes de iniciar. El proyecto responde al problema «algunos estudiantes quedan sin compañía en el recreo» y se probará con usuarios reales para comprobar interacciones positivas registradas.') on conflict(grade,parallel,group_number) do nothing;
