insert into public.aula_teams(grade,parallel,group_number,color_name,color_hex,team_name,project_title,project_description,project_problem,project_solution) values(4,'A',4,'Verde','#83d9ad','Grupo 4','Inclusión y accesibilidad','JuegosInclusivos Junior propone desarrollar tres juegos adaptados con tarjetas visuales para estudiantes en espacio escolar delimitado antes de iniciar. El proyecto responde al problema «algunos juegos excluyen por dificultad o reglas complejas» y se probará con usuarios reales para comprobar participación de estudiantes en cada juego.','Algunos juegos excluyen por dificultad o reglas complejas','JuegosInclusivos Junior propone desarrollar tres juegos adaptados con tarjetas visuales para estudiantes en espacio escolar delimitado antes de iniciar. El proyecto responde al problema «algunos juegos excluyen por dificultad o reglas complejas» y se probará con usuarios reales para comprobar participación de estudiantes en cada juego.') on conflict(grade,parallel,group_number) do nothing;
