insert into public.aula_teams(grade,parallel,group_number,color_name,color_hex,team_name,project_title,project_description,project_problem,project_solution) values(4,'B',5,'Lila','#aa9cec','Grupo 5','Desperdicio de alimentos','Food Waste Scale propone desarrollar registro comparativo de tres categorías para comedor / estudiantes. El proyecto responde al problema «no se conoce qué alimentos se desperdician con mayor frecuencia.» y deberá probarse con usuarios reales para comprobar categoría de mayor desperdicio.','No se conoce qué alimentos se desperdician con mayor frecuencia.','Food Waste Scale propone desarrollar registro comparativo de tres categorías para comedor / estudiantes. El proyecto responde al problema «no se conoce qué alimentos se desperdician con mayor frecuencia.» y deberá probarse con usuarios reales para comprobar categoría de mayor desperdicio.') on conflict(grade,parallel,group_number) do nothing;
