insert into public.aula_teams(grade,parallel,group_number,color_name,color_hex,team_name,project_title,project_description,project_problem,project_solution) values(4,'C',4,'Verde','#83d9ad','Grupo 4','Producto reciclado','EcoProducto Trace propone desarrollar stand con trazabilidad para comunidad escolar. El proyecto responde al problema «un producto reciclado gana valor cuando demuestra de dónde proviene y qué impacto evita.» y deberá probarse con usuarios reales para comprobar material recuperado.','Un producto reciclado gana valor cuando demuestra de dónde proviene y qué impacto evita.','EcoProducto Trace propone desarrollar stand con trazabilidad para comunidad escolar. El proyecto responde al problema «un producto reciclado gana valor cuando demuestra de dónde proviene y qué impacto evita.» y deberá probarse con usuarios reales para comprobar material recuperado.') on conflict(grade,parallel,group_number) do nothing;
