insert into public.aula_teams(grade,parallel,group_number,color_name,color_hex,team_name,project_title,project_description,project_problem,project_solution) values(4,'C',5,'Lila','#aa9cec','Grupo 5','Vivero escolar','Vivero Inteligente propone desarrollar catálogo y pedido simulado para familias / estudiantes. El proyecto responde al problema «un vivero escolar necesita orientar al comprador y organizar pedidos.» y deberá probarse con usuarios reales para comprobar pedidos completos.','Un vivero escolar necesita orientar al comprador y organizar pedidos.','Vivero Inteligente propone desarrollar catálogo y pedido simulado para familias / estudiantes. El proyecto responde al problema «un vivero escolar necesita orientar al comprador y organizar pedidos.» y deberá probarse con usuarios reales para comprobar pedidos completos.') on conflict(grade,parallel,group_number) do nothing;
