insert into public.aula_teams(grade,parallel,group_number,color_name,color_hex,team_name,project_title,project_description,project_problem,project_solution) values(4,'B',3,'Amarillo','#ffd465','Grupo 3','Señalética escolar','Señalética Smart propone desarrollar ruta con señalética probada para comunidad escolar. El proyecto responde al problema «algunas señales escolares no son suficientemente claras para todos los usuarios.» y deberá probarse con usuarios reales para comprobar señales comprendidas.','Algunas señales escolares no son suficientemente claras para todos los usuarios.','Señalética Smart propone desarrollar ruta con señalética probada para comunidad escolar. El proyecto responde al problema «algunas señales escolares no son suficientemente claras para todos los usuarios.» y deberá probarse con usuarios reales para comprobar señales comprendidas.') on conflict(grade,parallel,group_number) do nothing;
