insert into public.aula_teams(grade,parallel,group_number,color_name,color_hex,team_name,project_title,project_description,project_problem,project_solution) values(4,'B',4,'Verde','#83d9ad','Grupo 4','Productos personalizados','Bottle Custom Lab propone desarrollar producto + registro de hidratación para estudiantes / familias. El proyecto responde al problema «un producto cotidiano puede ganar valor al añadir una experiencia digital útil.» y deberá probarse con usuarios reales para comprobar registros de hidratación.','Un producto cotidiano puede ganar valor al añadir una experiencia digital útil.','Bottle Custom Lab propone desarrollar producto + registro de hidratación para estudiantes / familias. El proyecto responde al problema «un producto cotidiano puede ganar valor al añadir una experiencia digital útil.» y deberá probarse con usuarios reales para comprobar registros de hidratación.') on conflict(grade,parallel,group_number) do nothing;
