insert into public.aula_teams(grade,parallel,group_number,color_name,color_hex,team_name,project_title,project_description,project_problem,project_solution) values(4,'A',3,'Amarillo','#ffd465','Grupo 3','Identificación de útiles','Etiquetas Inteligentes propone desarrollar servicio con búsqueda simulada para estudiantes / familias. El proyecto responde al problema «los útiles sin identificación son difíciles de devolver cuando se pierden.» y deberá probarse con usuarios reales para comprobar objetos identificados.','Los útiles sin identificación son difíciles de devolver cuando se pierden.','Etiquetas Inteligentes propone desarrollar servicio con búsqueda simulada para estudiantes / familias. El proyecto responde al problema «los útiles sin identificación son difíciles de devolver cuando se pierden.» y deberá probarse con usuarios reales para comprobar objetos identificados.') on conflict(grade,parallel,group_number) do nothing;
