insert into public.aula_teams(grade,parallel,group_number,color_name,color_hex,team_name,project_title,project_description,project_problem,project_solution) values(4,'A',1,'Rosado','#ef8fba','Grupo 1','Servicio de pedidos','Pedidos por Turno propone desarrollar flujo de pedido completo para estudiantes. El proyecto responde al problema «los pedidos se desordenan cuando no existe una secuencia visible.» y deberá probarse con usuarios reales para comprobar pedidos entregados en orden.','Los pedidos se desordenan cuando no existe una secuencia visible.','Pedidos por Turno propone desarrollar flujo de pedido completo para estudiantes. El proyecto responde al problema «los pedidos se desordenan cuando no existe una secuencia visible.» y deberá probarse con usuarios reales para comprobar pedidos entregados en orden.') on conflict(grade,parallel,group_number) do nothing;
