insert into public.aula_teams(grade,parallel,group_number,color_name,color_hex,team_name,project_title,project_description,project_problem,project_solution) values(4,'A',2,'Celeste','#71c9e7','Grupo 2','Intercambio de objetos','Mercado Circular QR propone desarrollar mercado simulado con historial para comunidad escolar. El proyecto responde al problema «objetos útiles dejan de usarse aunque todavía tienen vida útil.» y deberá probarse con usuarios reales para comprobar intercambios / reutilizaciones.','Objetos útiles dejan de usarse aunque todavía tienen vida útil.','Mercado Circular QR propone desarrollar mercado simulado con historial para comunidad escolar. El proyecto responde al problema «objetos útiles dejan de usarse aunque todavía tienen vida útil.» y deberá probarse con usuarios reales para comprobar intercambios / reutilizaciones.') on conflict(grade,parallel,group_number) do nothing;
